class MedianFinder {
   public:
    priority_queue<int> leftMaxHeap;
    priority_queue<int, vector<int>, greater<int>> rightMinHeap;
    MedianFinder() {}

    void addNum(int num) {
        if (leftMaxHeap.empty() || num < leftMaxHeap.top())
            leftMaxHeap.push(num);
        else
            rightMinHeap.push(num);

        // so the left heap always should hold 1 extra element then right heap
        // in case of odd not more than 1 else they should hold equal elements
        // in even case

        if (leftMaxHeap.size() > rightMinHeap.size() + 1) {
            rightMinHeap.push(leftMaxHeap.top());
            leftMaxHeap.pop();
        } else if (rightMinHeap.size() > leftMaxHeap.size()) {
            leftMaxHeap.push(rightMinHeap.top());
            rightMinHeap.pop();
        }
    }

    double findMedian() {
        // if(leftMaxHeap.size() == rightMinHeap.size()) return (double)(leftMaxHeap.top() + rightMinHeap.top())/2;
